package net.civeira.phylax.feature.observe.observedissue.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.event.ObservedIssueEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedIssueEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedIssueEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedIssue entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
